class stringx { public: stringx(const stringx &); };
struct color32 { unsigned int value; };
class FEMenu { public: virtual void SetHelpText(int); };
class TextString { public: virtual void changeText(const stringx &); color32 color; };
class BoxText : public TextString { public: int makeBox(int, int, bool = false, float = -1.0f, int = -1); };
class kellyslater_controller { char padding[56]; int super_state; public: int get_super_state() { return super_state; } };
class world_dynamics_system { char padding[248]; kellyslater_controller *controller; public: kellyslater_controller *get_ks_controller(int) { return controller; } };
class IGOFrontEnd { public: bool IsMenuBGShown() const; void ShowMenuBackground(bool); void ShowAccompBackground(bool, int = 0, int = 0); };
struct FEManager { IGOFrontEnd *IGO; char padding[116]; color32 col_highlight; color32 col_info_b; };
class PauseMenuSystem {
    char padding[84];
public:
    enum { TipMenu = 8 };
    FEMenu *menus[9];
    FEManager *manager;
    bool IsResumable(FEMenu *) const;
};
struct game_layout { char padding[548]; int level_id; int get_level_id() const { return level_id; } };
struct career_level { char padding[36]; bool IsGoalDone(int) const; };
struct Career { char padding[65960]; career_level levels[1]; };
struct career_data { char padding[112]; int goal[5]; char tail[88]; };
class TipMenuClass : public FEMenu { public: stringx NextTip(); };
class GoalsMenuClass : public FEMenu {
    char padding0[20];
    TextString *status[5];
    char padding1[20];
public:
    PauseMenuSystem *sys;
    char padding2[36];
    BoxText *tip;
    bool show_tip;
    bool wasMenuBGOn;
    void SetAsTip();
    void SetNoTip();
    void OnActivate();
};
extern world_dynamics_system *g_world_ptr;
extern game_layout *g_game_ptr;
extern Career *g_career;
extern career_data CareerDataArray[];
extern stringx ksGlobalTextArray[];
enum {
    SUPER_STATE_FLYBY = 1,
    HF_BACK = 0x20,
    HF_RESUME = 0x40,
    MAX_GOALS_PER_LEVEL = 5,
    GOAL_NOTHING = 0,
    GT_GOALS_DONE = 0,
    GT_GOALS_NOT_DONE = 1
};

void GoalsMenuClass::OnActivate()
{
	// Don't show help text during flyby.
	if (g_world_ptr->get_ks_controller(0) && g_world_ptr->get_ks_controller(0)->get_super_state() == SUPER_STATE_FLYBY)
	{
		SetHelpText(0);
		tip->changeText(((TipMenuClass*) sys->menus[PauseMenuSystem::TipMenu])->NextTip());
		tip->makeBox(344, 100);
		SetAsTip();
		show_tip = true;
	}
	else
	{
		// If this menu was activated from the pause menu, then allow resume option.
		if (sys->IsResumable(this))
			SetHelpText(HF_BACK | HF_RESUME);
		else
			SetHelpText(HF_BACK);
		show_tip = false;
		SetNoTip();
	}

	// Set status to show if goal is done or not.
	for (int g = 0; g < MAX_GOALS_PER_LEVEL; g++)
	{
		if(CareerDataArray[g_game_ptr->get_level_id()].goal[g] != GOAL_NOTHING)
		{
			if (g_career->levels[g_game_ptr->get_level_id()].IsGoalDone(g))
			{
				status[g]->changeText(ksGlobalTextArray[GT_GOALS_DONE]);
				status[g]->color = sys->manager->col_highlight;
			}
			else
			{
				status[g]->changeText(ksGlobalTextArray[GT_GOALS_NOT_DONE]);
				status[g]->color = sys->manager->col_info_b;
			}
		}
	}

	wasMenuBGOn = sys->manager->IGO->IsMenuBGShown();
	sys->manager->IGO->ShowMenuBackground(false);
	sys->manager->IGO->ShowAccompBackground(true);
}
